def frames(lines):
    results = []
    data_buffer = []

    for line in lines:
        if line == "":
            # Blank line signals end of an event; dispatch it
            if data_buffer:
                results.append("\n".join(data_buffer))
            data_buffer = []
        elif line.startswith(":"):
            # Comment — ignore
            continue
        elif line.startswith("data:"):
            # Extract value, removing at most one leading space after the colon
            value = line[5:]
            if value.startswith(" "):
                value = value[1:]
            data_buffer.append(value)
        else:
            # Other field names (event, id, retry, etc.) — ignore
            continue

    # A trailing event without a blank-line terminator is discarded,
    # so we intentionally do NOT dispatch data_buffer here.
    return results
