def histogram(edges, values):
    if len(edges) < 2:
        raise ValueError("edges must contain at least two numbers")
    for i in range(1, len(edges)):
        if edges[i] <= edges[i - 1]:
            raise ValueError("edges must be strictly increasing")

    num_bins = len(edges) - 1
    counts = [0] * num_bins

    for v in values:
        if v < edges[0] or v > edges[-1]:
            continue
        for i in range(num_bins):
            if i == num_bins - 1:
                # Last bin is closed on both ends: [edge_i, edge_{i+1}]
                counts[i] += 1
                break
            if v < edges[i + 1]:
                # Half-open bin: [edge_i, edge_{i+1})
                counts[i] += 1
                break

    return counts
