def flatten(value):
    """
    Flatten a nested dictionary with string keys into a single-level
    dictionary with dot-separated keys.

    - Lists and scalar values are preserved as leaf values.
    - An empty dict leaf is represented as {} at its path.
    - An empty root {} produces {}.
    - Keys never contain dots.
    - The input is not mutated.
    """
    if not isinstance(value, dict):
        return value

    result = {}
    for key, val in value.items():
        if isinstance(val, dict):
            if not val:  # empty dict leaf
                result[key] = {}
            else:
                sub = flatten(val)
                for sub_key, sub_val in sub.items():
                    result[key + "." + sub_key] = sub_val
        else:
            result[key] = val
    return result
