def pack(items, max_bytes):
    if max_bytes < 1:
        raise ValueError("max_bytes must be >= 1")

    byte_lengths = []
    for item in items:
        blen = len(item.encode('utf-8'))
        if blen > max_bytes:
            raise ValueError(
                f"Item {item!r} has {blen} UTF-8 bytes, exceeding max_bytes={max_bytes}"
            )
        byte_lengths.append(blen)

    batches = []
    current_batch = []
    current_size = 0

    for item, blen in zip(items, byte_lengths):
        if current_size + blen <= max_bytes:
            current_batch.append(item)
            current_size += blen
        else:
            batches.append(current_batch)
            current_batch = [item]
            current_size = blen

    if current_batch:
        batches.append(current_batch)

    return batches
