import heapq
from collections import defaultdict


def order(deps):
    # Collect all nodes: keys in deps and nodes appearing only as prerequisites
    all_nodes = set(deps.keys())
    for prerequisites in deps.values():
        all_nodes.update(prerequisites)

    # Build in-degree counts and adjacency (prerequisite -> dependents)
    in_degree = {node: 0 for node in all_nodes}
    adj = defaultdict(list)

    for node, prerequisites in deps.items():
        for prereq in prerequisites:
            adj[prereq].append(node)
            in_degree[node] += 1

    # Kahn's algorithm — always pop the alphabetically smallest ready node
    heap = [node for node, deg in in_degree.items() if deg == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        current = heapq.heappop(heap)
        result.append(current)
        for dependent in adj[current]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                heapq.heappush(heap, dependent)

    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected")

    return result
